  1	/**
  2	 * Spreadsheet formula engine: tokenizer, recursive-descent parser, memoized
  3	 * dependency evaluation and reference rewriting.
  4	 *
  5	 * Sub-issue C of the spreadsheet workspace (Issue #5, decisions D-C1…D-C13).
  6	 * This is the single implementation shared by both sides of the application:
  7	 *
  8	 * - the frontend reaches it through `frontend/src/lib/formula.ts`, which the
  9	 *   display-value seam (`cellDisplay.ts`) and the copy/paste work (sub-issue D)
 10	 *   import from;
 11	 * - the backend imports `shared/formula.js` directly so a structural row/column
 12	 *   insert or delete can rewrite stored formula text in the same transaction
 13	 *   (decision D-C9).
 14	 *
 15	 * Supported grammar (`=` prefix required):
 16	 *
 17	 *   expr    := term (('+' | '-') term)*
 18	 *   term    := unary (('*' | '/') unary)*
 19	 *   unary   := '-' unary | primary
 20	 *   primary := number | reference | range | call | '(' expr ')' | '#REF!'
 21	 *   call    := NAME '(' expr (',' expr)* ')'
 22	 *
 23	 * with `NAME` case-insensitive in {SUM, AVERAGE, COUNT, MIN, MAX}. References
 24	 * are same-sheet A1 coordinates with optional `$` markers; ranges are `A1:B2`.
 25	 * `#REF!` is a first-class token so rewritten formulas (`=#REF!+A1`,
 26	 * `=SUM(#REF!)`) stay parseable. Cross-sheet references are not supported.
 27	 *
 28	 * Error values and their precedence (Issue #5 decision D-C2):
 29	 *
 30	 *   1. tokenizer failure                       -> #ERROR!
 31	 *   2. malformed syntax / reference shape      -> #ERROR!
 32	 *   3. unsupported function name (before args) -> #NAME?
 33	 *   4. first error met while evaluating        -> that error
 34	 *      left to right (division by zero -> #DIV/0!, invalid reference or a
 35	 *      dependency cycle -> #REF!)
 36	 *
 37	 * `evaluate` isolates failures per cell: one malformed formula never throws and
 38	 * never stops the other cells from being computed.
 39	 */
 40	
 41	import {
 42	  columnIndex,
 43	  columnLabel,
 44	  shiftRectOnDelete,
 45	  shiftRectOnInsert,
 46	} from './a1.js';
 47	
 48	/** @typedef {{ row: number, col: number, rowAbs: boolean, colAbs: boolean, colText: string }} RefPart */
 49	/** @typedef {'number' | 'ref' | 'range' | 'func' | 'op' | 'lparen' | 'rparen' | 'comma' | 'error'} TokenType */
 50	/**
 51	 * @typedef {Object} Token
 52	 * @property {TokenType} type
 53	 * @property {number} start
 54	 * @property {number} end
 55	 * @property {number} value
 56	 * @property {string} name
 57	 * @property {string} upper
 58	 * @property {string} op
 59	 * @property {RefPart | null} ref
 60	 * @property {RefPart | null} startPart
 61	 * @property {RefPart | null} endPart
 62	 */
 63	/**
 64	 * Single-shape AST node; `kind` selects which fields are meaningful.
 65	 *
 66	 * @typedef {Object} Node
 67	 * @property {string} kind
 68	 * @property {number} value
 69	 * @property {RefPart | null} ref
 70	 * @property {RefPart | null} startPart
 71	 * @property {RefPart | null} endPart
 72	 * @property {string} upper
 73	 * @property {string} op
 74	 * @property {Node | null} operand
 75	 * @property {Node | null} left
 76	 * @property {Node | null} right
 77	 * @property {Node[]} args
 78	 */
 79	/**
 80	 * A cell value during evaluation: exactly one of `blank`, `number` (in
 81	 * `number`), `text` (in `text`) or `error` (the error code in `text`).
 82	 *
 83	 * @typedef {Object} CellValue
 84	 * @property {'blank' | 'number' | 'text' | 'error'} kind
 85	 * @property {number} number
 86	 * @property {string} text
 87	 */
 88	/** @typedef {{ rowCount: number, colCount: number }} Bounds */
 89	
 90	const DIV0 = '#DIV/0!';
 91	const REF = '#REF!';
 92	const NAME = '#NAME?';
 93	const SYNTAX = '#ERROR!';
 94	
 95	const SUPPORTED_FUNCTIONS = new Set(['SUM', 'AVERAGE', 'COUNT', 'MIN', 'MAX']);
 96	
 97	const REF_HEAD = /^\$?([A-Za-z]+)\$?([1-9][0-9]*)/;
 98	const FUNC_HEAD = /^([A-Za-z][A-Za-z0-9_.]*)(?=\s*\()/;
 99	const NUMBER_HEAD = /^(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?/;
100	const NUMERIC_LITERAL = /^[+-]?(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?$/;
101	
102	/* ------------------------------------------------------------------ *
103	 * Small value helpers
104	 * ------------------------------------------------------------------ */
105	
106	/** @param {number} value @returns {CellValue} */
107	function numberValue(value) {
108	  return { kind: 'number', number: value, text: '' };
109	}
110	
111	/** @param {string} text @returns {CellValue} */
112	function textValue(text) {
113	  return { kind: 'text', number: 0, text };
114	}
115	
116	/** @param {string} code @returns {CellValue} */
117	function errorValue(code) {
118	  return { kind: 'error', number: 0, text: code };
119	}
120	
121	/** @returns {CellValue} */
122	function blankValue() {
123	  return { kind: 'blank', number: 0, text: '' };
124	}
125	
126	/** @param {CellValue} value @returns {CellValue} */
127	function toNumber(value) {
128	  if (value.kind === 'error' || value.kind === 'number') return value;
129	  return numberValue(0);
130	}
131	
132	/**
133	 * Display text for one evaluated formula result. Numbers use 15 significant
134	 * digits (decision D-C6): `=1/3` -> `0.333333333333333`, `=0.1+0.2` -> `0.3`.
135	 *
136	 * @param {CellValue} value
137	 * @returns {string}
138	 */
139	function displayText(value) {
140	  if (value.kind === 'text' || value.kind === 'error') return value.text;
141	  if (value.kind === 'blank') return '0';
142	  return formatNumber(value.number);
143	}
144	
145	/** @param {number} value @returns {string} */
146	function formatNumber(value) {
147	  if (!Number.isFinite(value)) return String(value);
148	  return String(Number(value.toPrecision(15)));
149	}
150	
151	/**
152	 * A raw cell value is a number only when, after trimming, the whole string is a
153	 * signed decimal/scientific literal. This rejects `0x10`, `Infinity`, `NaN`
154	 * and pure whitespace, so aggregates never treat a blank or the text `TRUE` as
155	 * a number (decision D-C5). Exported for re-use by the validation sub-issue.
156	 *
157	 * @param {string} raw
158	 * @returns {boolean}
159	 */
160	export function isNumericCellValue(raw) {
161	  if (typeof raw !== 'string') return false;
162	  const text = raw.trim();
163	  if (text === '') return false;
164	  return NUMERIC_LITERAL.test(text);
165	}
166	
167	/** @param {string} raw @returns {CellValue} */
168	function literalValue(raw) {
169	  if (isNumericCellValue(raw)) return numberValue(Number(raw.trim()));
170	  return textValue(raw);
171	}
172	
173	/* ------------------------------------------------------------------ *
174	 * Tokenizer
175	 * ------------------------------------------------------------------ */
176	
177	/** @param {string} ch @returns {boolean} */
178	function isSpace(ch) {
179	  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r';
180	}
181	
182	/** @param {string} ch @returns {boolean} */
183	function isLetter(ch) {
184	  return (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z');
185	}
186	
187	/** @param {TokenType} type @param {number} start @param {number} end @returns {Token} */
188	function makeToken(type, start, end) {
189	  return {
190	    type,
191	    start,
192	    end,
193	    value: 0,
194	    name: '',
195	    upper: '',
196	    op: '',
197	    ref: null,
198	    startPart: null,
199	    endPart: null,
200	  };
201	}
202	
203	/**
204	 * Match one A1 reference at `index` (`$A$1`, `A1`, `$A1`, `A$1`).
205	 *
206	 * @param {string} body
207	 * @param {number} index
208	 * @returns {{ part: RefPart, end: number } | null}
209	 */
210	function matchRef(body, index) {
211	  let j = index;
212	  let colAbs = false;
213	  if (body[j] === '$') {
214	    colAbs = true;
215	    j += 1;
216	  }
217	  let letters = '';
218	  while (j < body.length && isLetter(body[j])) {
219	    letters += body[j];
220	    j += 1;
221	  }
222	  if (letters === '') return null;
223	  let rowAbs = false;
224	  if (body[j] === '$') {
225	    rowAbs = true;
226	    j += 1;
227	  }
228	  let digits = '';
229	  while (j < body.length && body[j] >= '0' && body[j] <= '9') {
230	    digits += body[j];
231	    j += 1;
232	  }
233	  if (digits === '' || digits[0] === '0') return null;
234	  return {
235	    part: { row: Number(digits) - 1, col: columnIndex(letters), rowAbs, colAbs, colText: letters },
236	    end: j,
237	  };
238	}
239	
240	/**

240	/**
241	 * Tokenize the body of a formula (the text after the leading `=`).
242	 * Returns `{ ok: false }` for anything this grammar cannot lex, which the
243	 * callers translate into `#ERROR!` (evaluation) or "return unchanged"
244	 * (reference rewriting, which is deliberately lenient).
245	 *
246	 * @param {string} body
247	 * @returns {{ ok: true, tokens: Token[] } | { ok: false }}
248	 */
249	function tokenize(body) {
250	  const tokens = [];
251	  const length = body.length;
252	  let i = 0;
253	  while (i < length) {
254	    const ch = body[i];
255	    if (isSpace(ch)) {
256	      i += 1;
257	      continue;
258	    }
259	    if (ch === '(' || ch === ')' || ch === ',') {
260	      const type = /** @type {TokenType} */ (ch === '(' ? 'lparen' : ch === ')' ? 'rparen' : 'comma');
261	      tokens.push(makeToken(type, i, i + 1));
262	      i += 1;
263	      continue;
264	    }
265	    if (ch === '+' || ch === '-' || ch === '*' || ch === '/') {
266	      const token = makeToken('op', i, i + 1);
267	      token.op = ch;
268	      tokens.push(token);
269	      i += 1;
270	      continue;
271	    }
272	    if (ch === '#') {
273	      // `#REF!` is a first-class token; the `!` belongs to it and must not be
274	      // confused with a sheet-qualified reference (`Sheet2!A1` -> #ERROR!).
275	      if (body.startsWith('#REF!', i)) {
276	        tokens.push(makeToken('error', i, i + 5));
277	        i += 5;
278	        continue;
279	      }
280	      return { ok: false };
281	    }
282	    if (ch === '$' || isLetter(ch)) {
283	      const ref = matchRef(body, i);
284	      if (ref) {
285	        let k = ref.end;
286	        while (k < length && isSpace(body[k])) k += 1;
287	        if (body[k] === ':') {
288	          let m = k + 1;
289	          while (m < length && isSpace(body[m])) m += 1;
290	          const second = matchRef(body, m);
291	          if (!second) return { ok: false };
292	          const token = makeToken('range', i, second.end);
293	          token.startPart = ref.part;
294	          token.endPart = second.part;
295	          tokens.push(token);
296	          i = second.end;
297	          continue;
298	        }
299	        const token = makeToken('ref', i, ref.end);
300	        token.ref = ref.part;
301	        tokens.push(token);
302	        i = ref.end;
303	        continue;
304	      }
305	      const func = FUNC_HEAD.exec(body.slice(i));
306	      if (func) {
307	        const token = makeToken('func', i, i + func[1].length);
308	        token.name = func[1];
309	        token.upper = func[1].toUpperCase();
310	        tokens.push(token);
311	        i += func[1].length;
312	        continue;
313	      }
314	      return { ok: false };
315	    }
316	    const number = NUMBER_HEAD.exec(body.slice(i));
317	    if (number) {
318	      const token = makeToken('number', i, i + number[0].length);
319	      token.value = Number(number[0]);
320	      tokens.push(token);
321	      i += number[0].length;
322	      continue;
323	    }
324	    return { ok: false };
325	  }
326	  return { ok: true, tokens };
327	}
328	
329	/* ------------------------------------------------------------------ *
330	 * Parser
331	 * ------------------------------------------------------------------ */
332	
333	/** @param {string} kind @returns {Node} */
334	function makeNode(kind) {
335	  return {
336	    kind,
337	    value: 0,
338	    ref: null,
339	    startPart: null,
340	    endPart: null,
341	    upper: '',
342	    op: '',
343	    operand: null,
344	    left: null,
345	    right: null,
346	    args: [],
347	  };
348	}
349	
350	/**
351	 * Recursive-descent parse. Returns `null` on any syntax error (caller maps it
352	 * to `#ERROR!`). Function names are accepted syntactically even when unknown,
353	 * so `=FOO(1/0)` reaches the "unknown function wins over argument errors" rule.
354	 *
355	 * @param {Token[]} tokens
356	 * @returns {Node | null}
357	 */
358	function parse(tokens) {
359	  let pos = 0;
360	  const at = () => (pos < tokens.length ? tokens[pos] : null);
361	
362	  /** @returns {Node | null} */
363	  function parseExpr() {
364	    let left = parseTerm();
365	    if (!left) return null;
366	    let token = at();
367	    while (token && token.type === 'op' && (token.op === '+' || token.op === '-')) {
368	      pos += 1;
369	      const right = parseTerm();
370	      if (!right) return null;
371	      const node = makeNode('binary');
372	      node.op = token.op;
373	      node.left = left;
374	      node.right = right;
375	      left = node;
376	      token = at();
377	    }
378	    return left;
379	  }
380	
381	  /** @returns {Node | null} */
382	  function parseTerm() {
383	    let left = parseUnary();
384	    if (!left) return null;
385	    let token = at();
386	    while (token && token.type === 'op' && (token.op === '*' || token.op === '/')) {
387	      pos += 1;
388	      const right = parseUnary();
389	      if (!right) return null;
390	      const node = makeNode('binary');
391	      node.op = token.op;
392	      node.left = left;
393	      node.right = right;
394	      left = node;
395	      token = at();
396	    }
397	    return left;
398	  }
399	
400	  /** @returns {Node | null} */
401	  function parseUnary() {
402	    const token = at();
403	    if (token && token.type === 'op' && token.op === '-') {
404	      pos += 1;
405	      const operand = parseUnary();
406	      if (!operand) return null;
407	      const node = makeNode('neg');
408	      node.operand = operand;
409	      return node;
410	    }
411	    return parsePrimary();
412	  }
413	
414	  /** @returns {Node | null} */
415	  function parsePrimary() {
416	    const token = at();
417	    if (!token) return null;
418	    if (token.type === 'number') {
419	      pos += 1;
420	      const node = makeNode('number');
421	      node.value = token.value;
422	      return node;
423	    }
424	    if (token.type === 'ref') {
425	      pos += 1;
426	      const node = makeNode('ref');
427	      node.ref = token.ref;
428	      return node;
429	    }
430	    if (token.type === 'range') {
431	      pos += 1;
432	      const node = makeNode('range');
433	      node.startPart = token.startPart;
434	      node.endPart = token.endPart;
435	      return node;
436	    }
437	    if (token.type === 'error') {
438	      pos += 1;
439	      return makeNode('error');
440	    }
441	    if (token.type === 'lparen') {
442	      pos += 1;
443	      const inner = parseExpr();
444	      if (!inner) return null;
445	      const close = at();
446	      if (!close || close.type !== 'rparen') return null;
447	      pos += 1;
448	      return inner;
449	    }
450	    if (token.type === 'func') {
451	      pos += 1;
452	      const open = at();
453	      if (!open || open.type !== 'lparen') return null;
454	      pos += 1;
455	      const first = at();
456	      if (!first || first.type === 'rparen') return null;
457	      const args = [];
458	      for (;;) {
459	        const arg = parseExpr();
460	        if (!arg) return null;
461	        args.push(arg);
462	        const next = at();
463	        if (next && next.type === 'comma') {
464	          pos += 1;
465	          continue;
466	        }
467	        break;
468	      }
469	      const close = at();
470	      if (!close || close.type !== 'rparen') return null;
471	      pos += 1;
472	      const node = makeNode('call');
473	      node.upper = token.upper;
474	      node.args = args;
475	      return node;
476	    }
477	    return null;
478	  }
479	
480	  const root = parseExpr();
481	  if (!root || pos !== tokens.length) return null;
482	  return root;
483	}
484	
485	/* ------------------------------------------------------------------ *
486	 * Evaluation
487	 * ------------------------------------------------------------------ */
488	
489	/**
490	 * Evaluate a worksheet's cells and return the text each populated cell shows.
491	 *
492	 * The map contains one entry per populated cell, keyed `"row:col"` (0-based,
493	 * the same key `frontend/src/lib/coordinates.ts` uses): ordinary cells map to
494	 * their raw text, formula cells to the calculated result or an error string.
495	 * Unpopulated cells are absent (the caller renders `''`). Results are neither
496	 * cached across calls nor persisted — `cells.raw` stays the single fact source
497	 * and a reload simply recomputes (decisions D-C8, D-C13).
498	 *
499	 * `bounds` is the worksheet structure used to detect a single reference that
500	 * points outside the sheet (`=A7` on a 6-row sheet -> `#REF!`) and to clip
501	 * ranges (`=SUM(B1:B1000)` sums only the cells that exist). It is optional for
502	 * callers that evaluate standalone fragments; the display seam always passes
503	 * `row_count` / `col_count`, never the import footprint (decision D-C11).
504	 *
505	 * @param {Iterable<readonly [number, number, string]>} cells
506	 * @param {Bounds} [bounds]
507	 * @returns {Map<string, string>}
508	 */
509	export function evaluate(cells, bounds) {
510	  const rowCount = bounds && Number.isFinite(bounds.rowCount) ? bounds.rowCount : Infinity;
511	  const colCount = bounds && Number.isFinite(bounds.colCount) ? bounds.colCount : Infinity;
512	
513	  /** @type {Map<string, string>} */
514	  const raws = new Map();
515	  /** @type {{ row: number, col: number, raw: string }[]} */
516	  const entries = [];
517	  for (const [row, col, raw] of cells) {
518	    if (typeof raw !== 'string' || raw === '') continue;
519	    raws.set(`${row}:${col}`, raw);
520	    entries.push({ row, col, raw });
521	  }
522	
523	  /** @type {Map<string, CellValue>} */
524	  const cache = new Map();
525	  const visiting = new Set();
526	
527	  /** @param {number} row @param {number} col @returns {boolean} */
528	  const inBounds = (row, col) =>
529	    row >= 0 && col >= 0 && row < rowCount && col < colCount;
530	
531	  /**
532	   * Resolve one cell through the memoized dependency graph. Recursion follows
533	   * references, so a cell's inputs are always computed before it (the
534	   * topological order); a reference back into the `visiting` set is a direct or
535	   * indirect cycle and yields `#REF!` for every cell on the cycle.
536	   *
537	   * @param {number} row
538	   * @param {number} col
539	   * @returns {CellValue}
540	   */
541	  function valueOf(row, col) {
542	    const key = `${row}:${col}`;
543	    const cached = cache.get(key);
544	    if (cached) return cached;
545	    if (visiting.has(key)) return errorValue(REF);
546	    const raw = raws.get(key);
547	    if (raw === undefined) return blankValue();
548	    if (raw.startsWith('=')) {
549	      visiting.add(key);
550	      const value = normalizeScalar(evaluateFormula(raw));
551	      visiting.delete(key);
552	      cache.set(key, value);
553	      return value;
554	    }
555	    return literalValue(raw);
556	  }
557	
558	  /** @param {Node} node @returns {CellValue} */
559	  function evalNode(node) {
560	    switch (node.kind) {

560	    switch (node.kind) {
561	      case 'number':
562	        return numberValue(node.value);
563	      case 'error':
564	        return errorValue(REF);
565	      case 'ref': {
566	        const ref = node.ref;
567	        if (!ref) return errorValue(SYNTAX);
568	        if (!inBounds(ref.row, ref.col)) return errorValue(REF);
569	        return valueOf(ref.row, ref.col);
570	      }
571	      case 'range':
572	        // A rectangle is not a scalar; only aggregate calls consume it.
573	        return errorValue(SYNTAX);
574	      case 'neg': {
575	        const operand = node.operand ? evalNode(node.operand) : errorValue(SYNTAX);
576	        const coerced = toNumber(operand);
577	        if (coerced.kind === 'error') return coerced;
578	        return numberValue(-coerced.number);
579	      }
580	      case 'binary': {
581	        const left = node.left ? evalNode(node.left) : errorValue(SYNTAX);
582	        if (left.kind === 'error') return left;
583	        const right = node.right ? evalNode(node.right) : errorValue(SYNTAX);
584	        if (right.kind === 'error') return right;
585	        const a = toNumber(left);
586	        if (a.kind === 'error') return a;
587	        const b = toNumber(right);
588	        if (b.kind === 'error') return b;
589	        if (node.op === '+') return numberValue(a.number + b.number);
590	        if (node.op === '-') return numberValue(a.number - b.number);
591	        if (node.op === '*') return numberValue(a.number * b.number);
592	        if (node.op === '/') {
593	          if (b.number === 0) return errorValue(DIV0);
594	          return numberValue(a.number / b.number);
595	        }
596	        return errorValue(SYNTAX);
597	      }
598	      case 'call': {
599	        if (!SUPPORTED_FUNCTIONS.has(node.upper)) return errorValue(NAME);
600	        return evalAggregate(node.upper, node.args);
601	      }
602	      default:
603	        return errorValue(SYNTAX);
604	    }
605	  }
606	
607	  /**
608	   * Aggregate over every numeric value of the arguments: ranges contribute
609	   * only their numeric cells (blank and text cells are ignored, so empty cells
610	   * are never counted as zero), scalar arguments are evaluated and their
611	   * numeric results counted. An error anywhere in the arguments propagates
612	   * (decision D-C5 / assumption A-C6).
613	   *
614	   * @param {string} name
615	   * @param {Node[]} args
616	   * @returns {CellValue}
617	   */
618	  function evalAggregate(name, args) {
619	    let count = 0;
620	    let sum = 0;
621	    let min = Infinity;
622	    let max = -Infinity;
623	
624	    /** @param {CellValue} value */
625	    function absorb(value) {
626	      if (value.kind !== 'number') return;
627	      count += 1;
628	      sum += value.number;
629	      if (value.number < min) min = value.number;
630	      if (value.number > max) max = value.number;
631	    }
632	
633	    for (const arg of args) {
634	      if (arg.kind === 'range') {
635	        const start = arg.startPart;
636	        const end = arg.endPart;
637	        if (!start || !end) return errorValue(SYNTAX);
638	        for (const key of collectRangeKeys(start, end)) {
639	          const [row, col] = key.split(':').map(Number);
640	          const value = valueOf(row, col);
641	          if (value.kind === 'error') return value;
642	          absorb(value);
643	        }
644	      } else {
645	        const value = evalNode(arg);
646	        if (value.kind === 'error') return value;
647	        absorb(value);
648	      }
649	    }
650	
651	    if (name === 'SUM') return numberValue(sum);
652	    if (name === 'COUNT') return numberValue(count);
653	    if (name === 'MIN') return numberValue(count === 0 ? 0 : min);
654	    if (name === 'MAX') return numberValue(count === 0 ? 0 : max);
655	    if (name === 'AVERAGE') return count === 0 ? errorValue(DIV0) : numberValue(sum / count);
656	    return errorValue(NAME);
