659	  /**
660	   * Populated keys inside a range, clipped to the worksheet structure and
661	   * ordered row-major. Empty positions are skipped because they contribute
662	   * nothing to an aggregate (decision D-C11 clipping + D-C5 empty semantics).
663	   *
664	   * @param {RefPart} a
665	   * @param {RefPart} b
666	   * @returns {string[]}
667	   */
668	  function collectRangeKeys(a, b) {
669	    const r1 = Math.min(a.row, b.row);
670	    const r2 = Math.max(a.row, b.row);
671	    const c1 = Math.min(a.col, b.col);
672	    const c2 = Math.max(a.col, b.col);
673	    const keys = [];
674	    for (const entry of entries) {
675	      if (entry.row < r1 || entry.row > r2 || entry.col < c1 || entry.col > c2) continue;
676	      if (!inBounds(entry.row, entry.col)) continue;
677	      keys.push(`${entry.row}:${entry.col}`);
678	    }
679	    keys.sort((left, right) => {
680	      const [lr, lc] = left.split(':').map(Number);
681	      const [rr, rc] = right.split(':').map(Number);
682	      return lr - rr || lc - rc;
683	    });
684	    return keys;
685	  }
