687	  /**
688	   * Parse and evaluate one formula. Any lexer/parser failure becomes `#ERROR!`;
689	   * nothing throws (decision D-C2 step 1/2 and per-cell isolation).
690	   *
691	   * @param {string} raw
692	   * @returns {CellValue}
693	   */
694	  function evaluateFormula(raw) {
695	    const lexed = tokenize(raw.slice(1));
696	    if (!lexed.ok) return errorValue(SYNTAX);
697	    const ast = parse(lexed.tokens);
698	    if (!ast) return errorValue(SYNTAX);
699	    return evalNode(ast);
700	  }
701	
702	  /** @type {Map<string, string>} */
703	  const result = new Map();
704	  for (const entry of entries) {
705	    const key = `${entry.row}:${entry.col}`;
706	    if (entry.raw.startsWith('=')) {
707	      result.set(key, displayText(valueOf(entry.row, entry.col)));
708	    } else {
709	      result.set(key, entry.raw);
710	    }
711	  }
712	  return result;
713	}
