715	/**
716	 * A bare reference to an empty cell reads as 0 at the top level (`=A1` with an
717	 * empty A1 shows `0`), while `=A1` with text in A1 passes that text through.
718	 *
719	 * @param {CellValue} value
720	 * @returns {CellValue}
721	 */
722	function normalizeScalar(value) {
723	  return value.kind === 'blank' ? numberValue(0) : value;
