726	/* ------------------------------------------------------------------ *
727	 * Reference rewriting
728	 * ------------------------------------------------------------------ */
729	
730	/**
731	 * Re-emit one reference part with its original `$` markers and column-letter
732	 * case preserved (decision D-C4: the formula bar shows the user's text, so a
733	 * rewrite must not silently reformat it).
734	 *
735	 * @param {number} row
736	 * @param {number} col
737	 * @param {RefPart} original
738	 * @returns {string}
739	 */
740	function formatRefPart(row, col, original) {
741	  const rawLabel = col === original.col ? original.colText : columnLabel(col);
742	  const label = matchLetterCase(rawLabel, original.colText);
743	  return `${original.colAbs ? '$' : ''}${label}${original.rowAbs ? '$' : ''}${row + 1}`;
744	}
745	
746	/**
747	 * @param {string} label
748	 * @param {string} original
749	 * @returns {string}
750	 */
751	function matchLetterCase(label, original) {
752	  const lower = original === original.toLowerCase() && original !== original.toUpperCase();
753	  return lower ? label.toLowerCase() : label.toUpperCase();
754	}
