756	/**
757	 * Apply a token-level mapping to every reference in a formula, splicing the
758	 * replacements into the original text so operators, whitespace, function-name
759	 * case and `$` markers all survive untouched. Inputs the tokenizer cannot lex
760	 * are returned unchanged (deliberate leniency, decision D-C4).
761	 *
762	 * @param {string} formula
763	 * @param {(token: Token, original: string) => { collapse: boolean, text: string }} mapToken
764	 * @returns {string}
765	 */
766	function rewriteFormula(formula, mapToken) {
767	  if (typeof formula !== 'string' || !formula.startsWith('=')) return formula;
768	  const body = formula.slice(1);
769	  const lexed = tokenize(body);
770	  if (!lexed.ok) return formula;
771	  let out = '';
772	  let cursor = 0;
773	  for (const token of lexed.tokens) {
774	    if (token.type !== 'ref' && token.type !== 'range') continue;
775	    const mapped = mapToken(token, body.slice(token.start, token.end));
776	    if (mapped.collapse) return '=#REF!';
777	    out += body.slice(cursor, token.start) + mapped.text;
778	    cursor = token.end;
779	  }
780	  out += body.slice(cursor);
781	  return `=${out}`;
782	}
