784	/**
785	 * Rewrite a formula for a copy to another cell (REQ-4-1-2). Relative
786	 * components move by `(dRow, dCol)`; `$`-marked components stay.
787	 *
788	 * If the offset pushes **any** relative reference out of the target worksheet,
789	 * the whole formula collapses to the literal `=#REF!` (decision D-C3): the
790	 * requirement gives that exact string for the formula bar, and it holds for
791	 * both single- and multi-reference formulas. Pure absolute references cannot
792	 * move and therefore never trigger the collapse.
793	 *
794	 * `bounds` is the **target** worksheet's structure. A caller that first grows
795	 * the worksheet through the structure endpoint must pass the grown dimensions
796	 * (decision D-C3); the import footprint is never used here (decision D-C11).
797	 * This is a pure function: the input string is not modified.
798	 *
799	 * @param {string} formula
800	 * @param {number} dRow
801	 * @param {number} dCol
802	 * @param {Bounds} [bounds]
803	 * @returns {string}
804	 */
805	export function rewriteRefsOnCopy(formula, dRow, dCol, bounds) {
806	  const rowCount = bounds && Number.isFinite(bounds.rowCount) ? bounds.rowCount : Infinity;
807	  const colCount = bounds && Number.isFinite(bounds.colCount) ? bounds.colCount : Infinity;
808	
809	  /**
810	   * @param {RefPart} part
811	   * @returns {{ row: number, col: number, outside: boolean }}
812	   */
813	  const mapPart = (part) => {
814	    const row = part.row + (part.rowAbs ? 0 : dRow);
815	    const col = part.col + (part.colAbs ? 0 : dCol);
816	    const relative = !part.rowAbs || !part.colAbs;
817	    const outside = relative && (row < 0 || col < 0 || row >= rowCount || col >= colCount);
818	    return { row, col, outside };
819	  };
820	
821	  return rewriteFormula(formula, (token) => {
822	    if (token.type === 'ref') {
823	      const part = token.ref;
824	      if (!part) return { collapse: true, text: '' };
825	      const mapped = mapPart(part);
826	      if (mapped.outside) return { collapse: true, text: '' };
827	      return { collapse: false, text: formatRefPart(mapped.row, mapped.col, part) };
828	    }
829	    const start = token.startPart;
830	    const end = token.endPart;
831	    if (!start || !end) return { collapse: true, text: '' };
832	    const mappedStart = mapPart(start);
833	    const mappedEnd = mapPart(end);
834	    if (mappedStart.outside || mappedEnd.outside) return { collapse: true, text: '' };
835	    return {
836	      collapse: false,
837	      text: `${formatRefPart(mappedStart.row, mappedStart.col, start)}:${formatRefPart(
838	        mappedEnd.row,
839	        mappedEnd.col,
840	        end,
841	      )}`,
842	    };
843	  });
844	}
845	
846	/**
847	 * Rewrite a formula for a structural row/column insert or delete (REQ-4-2-1,
848	 * REQ-2-2-1/2-2-2). The coordinate mapping is the shared B-3 primitive in
849	 * `shared/a1.js`, so formulas and stored ranges move together:
850	 *
851	 * - insert `count` slots at `index`: references at or after it move by `count`;
852	 *   a range that receives the insertion expands, one entirely above it does not
853	 *   move. **Absolute references move too** — the requirement says all formula
854	 *   references shift (decision D-C4 / C-1b).
855	 * - delete at `index`: a reference to exactly that slot becomes a `#REF!`
856	 *   token, later references move up by one, an intersecting range shrinks
857	 *   (keeping its `:`), and a range that collapses becomes `#REF!`.
858	 *
859	 * Non-formula values and formulas the tokenizer cannot lex are returned
860	 * unchanged.
861	 *
862	 * @param {string} formula
863	 * @param {'row' | 'column'} axis
864	 * @param {number} index
865	 * @param {number} count
866	 * @param {boolean} [isDelete]
867	 * @returns {string}
868	 */
869	export function rewriteRefsOnInsertDelete(formula, axis, index, count, isDelete) {
870	  const remove = isDelete === true;
871	
872	  /**
873	   * @param {RefPart} a
874	   * @param {RefPart} b
875	   * @returns {{ r1: number, c1: number, r2: number, c2: number }}
876	   */
877	  const rectOf = (a, b) => {
878	    const rows = a.row <= b.row ? [a.row, b.row] : [b.row, a.row];
879	    const cols = a.col <= b.col ? [a.col, b.col] : [b.col, a.col];
880	    return { r1: rows[0], c1: cols[0], r2: rows[1], c2: cols[1] };
881	  };
882	
883	  /** @param {{ r1: number, c1: number, r2: number, c2: number }} rect */
884	  const mapRect = (rect) =>
885	    remove ? shiftRectOnDelete(rect, axis, index) : shiftRectOnInsert(rect, axis, index, count);
886	
887	  return rewriteFormula(formula, (token, original) => {
888	    if (token.type === 'ref') {
889	      const part = token.ref;
890	      if (!part) return { collapse: false, text: REF };
891	      const result = mapRect({ r1: part.row, c1: part.col, r2: part.row, c2: part.col });
892	      if (result === null) return { collapse: false, text: REF };
893	      if (!result.changed) return { collapse: false, text: original };
894	      return {
895	        collapse: false,
896	        text: formatRefPart(result.rect.r1, result.rect.c1, part),
897	      };
898	    }
899	    const start = token.startPart;
900	    const end = token.endPart;
901	    if (!start || !end) return { collapse: false, text: REF };
902	    const result = mapRect(rectOf(start, end));
903	    if (result === null) return { collapse: false, text: REF };
904	    if (!result.changed) return { collapse: false, text: original };
905	    return {
906	      collapse: false,
907	      text: `${formatRefPart(result.rect.r1, result.rect.c1, start)}:${formatRefPart(
908	        result.rect.r2,
909	        result.rect.c2,
910	        end,
911	      )}`,
912	    };
913	  });
914	}

  1	/**
  2	 * A1-notation primitives shared by the backend structure endpoints and the
  3	 * formula engine (sub-issue C, Issue #5 decision D-C1/D-C7).
  4	 *
  5	 * This module was migrated verbatim from `backend/src/ranges.js` (sub-issue B,
  6	 * Issue #4 comment #35 D-B3) so that both consumers map coordinates through a
  7	 * single implementation: `backend/src/ranges.js` re-exports the public names
  8	 * and keeps its behaviour byte-for-byte.
  9	 *
 10	 * Two views of the same coordinate mapping:
 11	 *
 12	 * - **range view** (`shiftRangeOnInsert` / `shiftRangeOnDelete`) formats the
 13	 *   result with {@link formatA1Range}, which strips `$` markers, collapses a
 14	 *   1x1 rectangle to a single reference and uppercases the column letters. It
 15	 *   is what B persists for validation rules, filters and pivot source ranges.
 16	 * - **rect view** (`shiftRectOnInsert` / `shiftRectOnDelete`) returns the
 17	 *   mapped rectangle without formatting, so the formula engine can re-emit a
 18	 *   reference preserving the user's `$` markers, `:` separator and letter case
 19	 *   (Issue #5 decision D-C4).
 20	 *
 21	 * Mapping rules (Issue #4 comment #35 D-B3):
 22	 *
 23	 * - Insert at the new block's first index `p`, `count` slots: `p <= r1` shifts
 24	 *   the whole range; `r1 < p <= r2` expands the range by `count` (an insertion
 25	 *   inside a region stays inside it); `p > r2` changes nothing.
 26	 * - Delete at `d`: `d < r1` shifts the whole range; `r1 <= d <= r2` shrinks it
 27	 *   by one with `r1` fixed (`r2 -= 1`); a range that collapses (`r1 > r2`,
 28	 *   i.e. exactly the deleted single row/column) is reported as `null`.
 29	 *
 30	 * Parsing is deliberately lenient: any expression this module cannot parse is
 31	 * returned unchanged (`changed: false`) so an unknown stored format is never
 32	 * corrupted by a structure operation.
 33	 */
 34	
 35	/** @typedef {{ r1: number, c1: number, r2: number, c2: number }} Rect */
 36	/** @typedef {'row' | 'column'} Axis */
 37	/** @typedef {{ range: string, changed: boolean }} ShiftResult */
 38	
 39	const A1_RANGE = /^\$?([A-Za-z]+)\$?([1-9][0-9]*)(?::\$?([A-Za-z]+)\$?([1-9][0-9]*))?$/;
 40	
 41	/**
 42	 * Column index (0-based) to spreadsheet letters: 0 -> "A", 25 -> "Z", 26 -> "AA".
 43	 *
 44	 * @param {number} col
 45	 * @returns {string}
 46	 */
 47	export function columnLabel(col) {
 48	  let value = col + 1;
 49	  let label = '';
 50	  while (value > 0) {
 51	    const remainder = (value - 1) % 26;
 52	    label = String.fromCharCode(65 + remainder) + label;
 53	    value = Math.floor((value - 1) / 26);
 54	  }
 55	  return label;
 56	}
 57	
 58	/**
 59	 * Spreadsheet letters to a 0-based column index: "A" -> 0, "AA" -> 26.
 60	 *
 61	 * @param {string} letters
 62	 * @returns {number}
 63	 */
 64	export function columnIndex(letters) {
 65	  let col = 0;
 66	  for (const character of letters.toUpperCase()) {
 67	    col = col * 26 + (character.charCodeAt(0) - 64);
 68	  }
 69	  return col - 1;
 70	}
 71	
 72	/**
 73	 * Parse an A1-style range (`"B2"`, `"B2:B10"`, `"$B$2:$D$10"`).
 74	 *
 75	 * @param {string} text
 76	 * @returns {Rect | null}
 77	 */
 78	export function parseA1Range(text) {
 79	  if (typeof text !== 'string') return null;
 80	  const match = A1_RANGE.exec(text.trim());
 81	  if (!match) return null;
 82	  const c1 = columnIndex(match[1]);
 83	  const r1 = Number.parseInt(match[2], 10) - 1;
 84	  const c2 = match[3] === undefined ? c1 : columnIndex(match[3]);
 85	  const r2 = match[4] === undefined ? r1 : Number.parseInt(match[4], 10) - 1;
 86	  return {
 87	    r1: Math.min(r1, r2),
 88	    c1: Math.min(c1, c2),
 89	    r2: Math.max(r1, r2),
 90	    c2: Math.max(c1, c2),
 91	  };
 92	}
 93	
 94	/**
 95	 * Serialise a rectangle back to A1 notation. A 1x1 rectangle serialises to a
 96	 * single reference (`"B2"`), everything else to `"B2:D10"`.
 97	 *
 98	 * @param {Rect} rect
 99	 * @returns {string}
100	 */
101	export function formatA1Range(rect) {
102	  const start = `${columnLabel(rect.c1)}${rect.r1 + 1}`;
103	  if (rect.r1 === rect.r2 && rect.c1 === rect.c2) return start;
104	  return `${start}:${columnLabel(rect.c2)}${rect.r2 + 1}`;
105	}
106	
107	/**
108	 * Map a rectangle through the insert rule, returning the mapped rectangle and
109	 * whether anything moved. This is the shared primitive the formula rewrite uses
110	 * (the range view below formats its result).
111	 *
112	 * @param {Rect} rect
113	 * @param {Axis} axis
114	 * @param {number} at
115	 * @param {number} count
116	 * @returns {{ rect: Rect, changed: boolean }}
117	 */
118	export function shiftRectOnInsert(rect, axis, at, count) {
119	  const loKey = axis === 'row' ? 'r1' : 'c1';
120	  const hiKey = axis === 'row' ? 'r2' : 'c2';
121	  /** @type {Rect} */
122	  const next = { ...rect };
123	  if (at <= rect[loKey]) {
124	    next[loKey] += count;
125	    next[hiKey] += count;
126	    return { rect: next, changed: true };
127	  }
128	  if (at <= rect[hiKey]) {
129	    next[hiKey] += count;
130	    return { rect: next, changed: true };
131	  }
132	  return { rect: next, changed: false };
133	}
134	
135	/**
136	 * Map a rectangle through the delete rule. `null` means the rectangle collapsed
137	 * (it was exactly the deleted slot) and can no longer be represented.
138	 *
139	 * @param {Rect} rect
140	 * @param {Axis} axis
141	 * @param {number} at
142	 * @returns {{ rect: Rect, changed: boolean } | null}
143	 */
144	export function shiftRectOnDelete(rect, axis, at) {
145	  const loKey = axis === 'row' ? 'r1' : 'c1';
146	  const hiKey = axis === 'row' ? 'r2' : 'c2';
147	  /** @type {Rect} */
148	  const next = { ...rect };
149	  if (at < rect[loKey]) {
150	    next[loKey] -= 1;
151	    next[hiKey] -= 1;
152	    return { rect: next, changed: true };
153	  }
154	  if (at <= rect[hiKey]) {
155	    next[hiKey] -= 1;
156	    if (next[loKey] > next[hiKey]) return null;
157	    return { rect: next, changed: true };
158	  }
159	  return { rect: next, changed: false };
160	}
161	
162	/**
163	 * Shift a stored range for an insertion of `count` slots at index `at`.
164	 * Returns the original text untouched when it cannot be parsed.
165	 *
166	 * @param {string} range
167	 * @param {Axis} axis
168	 * @param {number} at
169	 * @param {number} count
170	 * @returns {ShiftResult}
171	 */
172	export function shiftRangeOnInsert(range, axis, at, count) {
173	  const rect = parseA1Range(range);
174	  if (!rect) return { range, changed: false };
175	  const { rect: next, changed } = shiftRectOnInsert(rect, axis, at, count);
176	  return { range: changed ? formatA1Range(next) : range, changed };
177	}
178	
179	/**
180	 * Shift a stored range for a deletion at index `at`.
181	 *
182	 * @param {string} range
183	 * @param {Axis} axis
184	 * @param {number} at
185	 * @returns {{ range: string | null, changed: boolean }} `range === null` = remove.
186	 */
187	export function shiftRangeOnDelete(range, axis, at) {
188	  const rect = parseA1Range(range);
189	  if (!rect) return { range, changed: false };
190	  const result = shiftRectOnDelete(rect, axis, at);
191	  if (result === null) return { range: null, changed: true };
192	  return { range: result.changed ? formatA1Range(result.rect) : range, changed: result.changed };
193	}

