+/**
+ * Rewrite the references of every `=`-prefixed cell of one worksheet after a
+ * structural insert/delete (sub-issue C, Issue #5 decisions D-C9/D-C9a).
+ *
+ * This runs inside the structure endpoint's transaction, **before** the cell
+ * movement, so it reads and writes the pre-shift coordinate space in place: the
+ * two-phase `shiftCells` update that follows carries the rewritten raw text to
+ * the new coordinates. `deleteStructure` deletes the target row/column first, so
+ * removed data never participates. The rewrite direction is never inferred from
+ * the stored state: the caller passes `{ kind, at, count }` explicitly.
+ *
+ * A throw from the shared rewrite rolls back the whole transaction (including
+ * the dimension update), as with every other step of these endpoints — the
+ * structure endpoints' failure-atomicity tests cover it.
+ *
+ * @param {Db} db
+ * @param {string} worksheetId
+ * @param {'row' | 'column'} axis
+ * @param {{ kind: 'insert', at: number, count: number } | { kind: 'delete', at: number }} op
+ * @returns {void}
+ */
+function rewriteFormulaCells(db, worksheetId, axis, op) {
+  const cells = /** @type {{ row: number, col: number, raw: string }[]} */ (
+    db.prepare('SELECT row, col, raw FROM cells WHERE worksheet_id = ?').all(worksheetId)
+  );
+  const update = db.prepare(
+    'UPDATE cells SET raw = ? WHERE worksheet_id = ? AND row = ? AND col = ?',
+  );
+  for (const cell of cells) {
+    if (!cell.raw.startsWith('=')) continue;
+    const next =
+      op.kind === 'insert'
+        ? rewriteRefsOnInsertDelete(cell.raw, axis, op.at, op.count)
+        : rewriteRefsOnInsertDelete(cell.raw, axis, op.at, 1, true);
+    if (next !== cell.raw) update.run(next, worksheetId, cell.row, cell.col);
+  }
